using System.Net;
using System.Text;
using System.Text.RegularExpressions;

namespace NordicBeesERP.Services.Email;

/// <summary>
/// Pure conversion between the template HTML and the plain text a user edits in the send dialog.
/// HTML tables (generated by code, e.g. {{InvoiceTable}}) are not editable: they are cut out as a fixed block that is
/// appended after the edited text on send. Everything the user types is HTML-encoded.
/// </summary>
public static class EmailBodyText
{
    private static readonly Regex Table = new(@"<table\b.*?</table>", RegexOptions.Singleline | RegexOptions.IgnoreCase | RegexOptions.Compiled);
    private static readonly Regex ParagraphBreak = new(@"</p>\s*<p\b[^>]*>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    private static readonly Regex Br = new(@"<br\s*/?>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
    private static readonly Regex AnyTag = new(@"<[^>]+>", RegexOptions.Singleline | RegexOptions.Compiled);
    private static readonly Regex BlankLines = new(@"\n[ \t]*\n(?:[ \t]*\n)*", RegexOptions.Compiled);

    /// <summary>Editable text plus the fixed (non-editable) HTML blocks that were cut out of the template.</summary>
    public static (string Text, string FixedHtml) ToPlainText(string html)
    {
        var fixedBlocks = new StringBuilder();
        var rest = Table.Replace(html ?? string.Empty, m =>
        {
            fixedBlocks.Append(m.Value);
            return "\n\n";
        });

        rest = ParagraphBreak.Replace(rest, "\n\n");
        rest = Br.Replace(rest, "\n");
        rest = Regex.Replace(rest, @"</p\s*>", "\n\n", RegexOptions.IgnoreCase);
        rest = AnyTag.Replace(rest, string.Empty);
        rest = WebUtility.HtmlDecode(rest).Replace("\r\n", "\n").Replace('\r', '\n').Replace(' ', ' ');
        rest = BlankLines.Replace(rest, "\n\n").Trim();
        return (rest, fixedBlocks.ToString());
    }

    /// <summary>Blank line = new paragraph, single newline = &lt;br&gt;; text is HTML-encoded; the fixed block follows.</summary>
    public static string ToHtml(string? text, string? fixedHtml)
    {
        var normalized = (text ?? string.Empty).Replace("\r\n", "\n").Replace('\r', '\n').Trim();
        var sb = new StringBuilder();
        if (normalized.Length > 0)
        {
            foreach (var paragraph in BlankLines.Split(normalized))
            {
                var p = paragraph.Trim('\n', ' ', '\t');
                if (p.Length == 0) continue;
                sb.Append("<p>").Append(WebUtility.HtmlEncode(p).Replace("\n", "<br>")).Append("</p>");
            }
        }

        return sb.Append(fixedHtml ?? string.Empty).ToString();
    }
}
